mapper.select:
SELECT
-- 应急事件总数
(SELECT IFNULL(SUM(total_rpt_count), 0)
    FROM stat_mon_evt_rpt


            stat_cycle = #{statCycle}


            AND region_code = #{shortCode}


) AS total_evt_count,

-- 在处置事件数
(SELECT IFNULL(SUM(handl_count), 0)
    FROM stat_mon_evt_rpt


            stat_cycle = #{statCycle}


            AND region_code = #{shortCode}


) AS handl_count,

-- 已办结事件数
(SELECT IFNULL(SUM(completed_count), 0)
    FROM stat_mon_evt_rpt


            stat_cycle = #{statCycle}


            AND region_code = #{shortCode}


) AS completed_count,

-- 应急资源总数
(SELECT IFNULL(SUM(stock_qty), 0)
    FROM biz_emerg_res


            region_code = #{shortCode}


            AND stat_cycle = #{statCycle}


) AS total_res_count,

-- 高风险隐患数
(SELECT IFNULL(COUNT(*), 0)
    FROM biz_risk_hazard


            region_code = #{shortCode}


            AND stat_cycle = #{statCycle}


) AS high_risk_count,

-- 行政区划覆盖数(仅下一级)
(SELECT IFNULL(COUNT(*), 0)
    FROM sys_area


            parent_id = (SELECT id FROM sys_area WHERE short_code = #{shortCode})


) AS region_cover_count
